public async Task<Resultado<ConversaDto>> ObterConversa(string conversaId)
{
    var conversa = await _conversas.Find(c => c.Id == conversaId).FirstOrDefaultAsync();   // linha 1

    if (conversaId == null)                                                              // linha 2
        return Resultado<ConversaDto>.Falha("Conversa não encontrada");

    return Resultado<ConversaDto>.Ok(new ConversaDto { Titulo = conversa.Titulo });        // linha 3
}

